arguments.command:
curl -s -X POST "https://slack.com/api/conversations.history" -H "Authorization: Bearer <TOKEN>" -d "channel=C_81&limit=999" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit(0)
for m in d['messages']:
    rx = m.get('reactions', [])
    if rx:
        users = set()
        for r in rx:
            for u in r.get('users',[]): users.add(u)
        print(m['ts'], '|', m.get('user'), '|', m.get('text','')[:100])
        for r in rx: print('   ', r['name'], r.get('users'))
"

